// ---------------------------------------------------------------------------
// Registration
// ---------------------------------------------------------------------------

export interface IRegistrationRepository {
  createWithRelations(insertSet: RegistrationInsertSet): Promise<{ id: number }>;

  /** Returns the registration for the given internal id, or null. */
  findById(id: number): Promise<Registration | null>;

  /** Returns the registration for the given public-facing regCode, or null. */
  findByRegCode(regCode: string): Promise<Registration | null>;

  /** Returns all registrations associated with the given email address. */
  findByEmail(email: string): Promise<Registration[]>;

  /** Returns all registrations associated with the given WhatsApp number. */
  findByWhatsapp(whatsapp: string): Promise<Registration[]>;

  /** Updates the status of a registration. Caller must validate the transition. */
  updateStatus(id: number, status: RegistrationStatus): Promise<void>;

  /**
   * Partially updates a registration's fields and optionally replaces attendees.
   * Only fields present in `data` are updated.
   */
  update(id: number, data: RegistrationUpdate, attendees?: NewAttendee[]): Promise<void>;

  /**
   * Updates registration fields with optimistic locking.
   * Throws Error('OPTIMISTIC_LOCK_CONFLICT') if updated_at does not match
   * expectedUpdatedAt (concurrent modification detected).
   * Optionally replaces all attendees (delete + re-insert) when provided.
   */
  updateWithLock(
    id: number,
    data: RegistrationUpdate,
    expectedUpdatedAt: number,
    attendees?: NewAttendee[],
  ): Promise<void>;

  /** Returns registrations matching the optional filters. */
  list(filters?: RegistrationFilters): Promise<Registration[]>;

  /** Returns the total count of registrations matching the optional filters. */
  count(filters?: RegistrationFilters): Promise<number>;

  /** Returns registrations that have a photo but no thumbnail. */
  findMissingThumbnails(): Promise<Array<{ id: number; regCode: string; photoFileKey: string }>>;

  /** Returns registrations that have a thumbnail generated. */
  findWithThumbnails(): Promise<Array<{ id: number; photoThumbKey: string }>>;

  /**
   * Returns registration counts grouped by status, optionally filtered by type.
   * Missing statuses default to 0.
   */
  countByStatus(filters?: { type?: 'attendee' | 'donor' }): Promise<{
    pending: number;
    pendingVerification: number;
    confirmed: number;
  }>;

  /**
   * Returns city and country registration counts for attending registrations
   * (participation_type IN ('full_celebration', 'campus_only')) in a single combined query.
   * Results sorted count DESC. Blank or NULL city/country bucketed as "Unknown" (B4).
   */
  geographyAggregates(): Promise<{
    cities: { city: string; count: number }[];
    countries: { country: string; count: number }[];
  }>;

  /**
   * Returns donor recognition data in a single query pass:
   * - publicDonors: registrations with donation_amount > 0 AND public_ack = 1,
   *   sorted donation_amount DESC. displayName falls back to full_name when
   *   ack_display_name is blank (B5). felicitationEligible computed as
   *   (felicitation = 1 AND donation_amount >= felicitationThreshold) — D1
   *   returns 0|1, never compare as === true (T2-10).
   * - nonPublicCount + nonPublicTotal: aggregate for public_ack = 0 donors.
   */
  donorRecognitionRows(felicitationThreshold: number): Promise<{
    publicDonors: { displayName: string; amount: number; felicitationEligible: boolean }[];
    nonPublicCount: number;
    nonPublicTotal: number;
  }>;

  /**
   * Returns registration counts grouped by participation_type × status in a
   * single GROUP BY query. Always unfiltered — returns counts across all
   * registration types. Missing participation_type/status combinations default
   * to 0 in the returned shape.
   *
   * Shape: { full_celebration, campus_only, donation_only } each containing
   * { total, confirmed, pending, pendingVerification }.
   */
  countByParticipationAndStatus(): Promise<Record<
    'full_celebration' | 'campus_only' | 'donation_only',
    { total: number; confirmed: number; pending: number; pendingVerification: number }
  >>;

  /**
   * Returns per-cause contribution aggregates across ALL registrations (including
   * donation-only). Uses D1 json_each to expand the contribution_splits JSON map.
   * Causes with zero entries are omitted.
   */
  getContributionAggregates(): Promise<Array<{
    cause: string;
    count: number;
    total: number;
  }>>;

  /**
   * Returns reunion donation count and total across ALL registrations that have
   * donation_amount > 0, regardless of payment status.
   */
  getDonationTotals(): Promise<{ count: number; total: number }>;
}

// ---------------------------------------------------------------------------
// Attendee
// ---------------------------------------------------------------------------

export interface IAttendeeRepository {
  /** Returns all attendees for the given registration. */
  findByRegistration(registrationId: number): Promise<Attendee[]>;

  /**
   * Deletes all existing attendees for the registration and inserts the
   * provided list. Used for amendments where the attendee list changes.
   */
  replaceForRegistration(registrationId: number, attendees: NewAttendee[]): Promise<void>;

  /**
   * Returns attendee counts grouped by type and meal preference.
   * Only includes attendees belonging to non-donation registrations.
   * Optionally filtered by registration statuses and/or branch.
   */
  countGrouped(filters?: { statuses?: string[]; branch?: string }): Promise<Array<{
    type: string;
    meal: string;
    count: number;
  }>>;

  /**
   * Returns per-night occupancy using the [check_in, check_out) interval:
   * a stay check_in=2026-08-14/check_out=2026-08-16 appears in BOTH night
   * buckets "2026-08-14" and "2026-08-15" (decision C6).
   *
   * Both night keys are always present in the result (T2-11), even when zero.
   * Excludes accommodation='none' and rows with NULL check_in (C1).
   * Excludes donation_only registrations (C8).
   * Honors status and branch filters (T2-6).
   *
   * Shape per night: private headcount, shared_double {count, rooms=ceil(n/2)},
   * shared_triple {count, rooms=ceil(n/3)}, extraBeds.
   */
  accommodationByNight(filters?: { statuses?: string[]; branch?: string }): Promise<Record<string, {
    private: number;
    privateByGender: { male: number; female: number; other: number };
    shared_double: { count: number; rooms: number };
    shared_doubleByGender: { male: number; female: number; other: number };
    shared_triple: { count: number; rooms: number };
    shared_tripleByGender: { male: number; female: number; other: number };
    extraBeds: number;
  }>>;

  /**
   * Returns meal headcounts split by caterer bucket (decision C7):
   *   campusDayCaterer = full_celebration + campus_only alumni + their attendees.
   *   ravizBanquet = full_celebration alumni + their attendees only.
   *
   * Two GROUP BY queries (alumni from registrations; attendees via JOIN).
   * No per-registration loops (T2-1). Excludes donation_only (C8).
   * Honors status and branch filters (T2-6).
   */
  mealsByParticipationType(filters?: { statuses?: string[]; branch?: string }): Promise<{
    campusDayCaterer: { headcount: number; veg: number; nonVeg: number };
    ravizBanquet: { headcount: number; veg: number; nonVeg: number };
  }>;

  /**
   * Returns children counts split by age band (decision C4):
   *   under6:   age < 6 OR age IS NULL
   *   age6to12: 6 <= age < 12
   *   age12plus: age >= 12
   *
   * Single GROUP BY query on attendees WHERE type='child'.
   * Filters by parent registration status/branch (T2-6).
   * Excludes donation_only parent registrations (C8).
   */
  childrenByAgeBand(filters?: { statuses?: string[]; branch?: string }): Promise<{
    under6: number;
    age6to12: number;
    age12plus: number;
  }>;
}

// ---------------------------------------------------------------------------
// Payment
// ---------------------------------------------------------------------------

export interface IPaymentRepository {
  /** Inserts a new payment record and returns its autoincrement id. */
  create(payment: NewPayment): Promise<{ id: number }>;

  /** Returns a single payment by its internal id, or null if not found. */
  findById(id: number): Promise<Payment | null>;

  /** Returns all payment attempts for the given registration. */
  findByRegistration(registrationId: number): Promise<Payment[]>;

  /**
   * Updates the status of a payment and optionally records gateway data,
   * proof file key, and/or verification data. Caller must validate the
   * transition with isValidPaymentTransition.
   */
  updateStatus(
    id: number,
    status: PaymentStatus,
    gatewayData?: GatewayData,
    proofFileKey?: string,
    verification?: { verifiedBy: string; verifiedAt: number },
  ): Promise<void>;

  /**
   * Returns the single payment_pending record for the registration, or null.
   * Invariant: at most one payment_pending per registration.
   */
  findPendingByRegistration(registrationId: number): Promise<Payment | null>;

  /**
   * Deletes a payment record. Guard: only deletes payment_pending records.
   * Deleting a non-payment_pending record is a no-op (SQL WHERE clause guards it).
   */
  deletePending(paymentId: number): Promise<void>;

  /**
   * Updates the amount of a payment_pending record.
   * Guard: only updates payment_pending records — never touches frozen payments.
   */
  updatePendingAmount(paymentId: number, newAmount: number): Promise<void>;

  /**
   * Atomically verifies a payment: sets status='verified', overwrites amount,
   * records gateway_ref, verified_by, verified_at. WHERE guards on
   * status='pending_verification' — concurrent verify is a no-op.
   */
  verify(
    id: number,
    amount: number,
    gatewayRef: string,
    verifiedBy: string,
    verifiedAt: number,
  ): Promise<void>;

  /**
   * Desk cash/UPI/bank-transfer settlement: sets status='verified', overwrites
   * amount, records method, note, verified_by, verified_at. WHERE guards on
   * status IN ('payment_pending', 'pending_verification') — a payment already
   * verified (or missing) is a no-op, mirroring verify()'s guarded-UPDATE
   * posture. Distinct from verify() because desk settlement has no gateway
   * reference and settles the full outstanding balance, never a partial or
   * proof-reviewed amount.
   */
  settleAtDesk(
    id: number,
    args: {
      amount: number;
      method: DeskPaymentMethod;
      note: string | null;
      verifiedBy: string;
      verifiedAt: number;
    },
  ): Promise<void>;

  /**
   * Returns the sum of all VERIFIED payment amounts for a specific registration.
   * Used during staff edit to compute how much has already been received.
   */
  sumVerifiedByRegistration(registrationId: number): Promise<number>;

  /**
   * Returns the sum of all verified payment amounts, optionally filtered
   * by registration type (attendee vs donor).
   */
  sumVerified(filters?: { type?: 'attendee' | 'donor' }): Promise<number>;

  /**
   * Returns verified payment totals grouped by branch, optionally filtered
   * by registration type.
   */
  sumVerifiedByBranch(filters?: { type?: 'attendee' | 'donor' }): Promise<Array<{
    branch: string;
    collected: number;
  }>>;
}

