export interface ITshirtRepository {
  /** Returns all shirt rows (included + extras) for a registration, ordered created_at ASC. */
  findByRegistration(registrationId: number): Promise<Tshirt[]>;

  /**
   * Returns every shirt row across ALL registrations in one query. Used by
   * the staff resources matrix, which needs a per-registration breakdown
   * without an N+1 query per registration — callers filter/group in memory.
   */
  findAll(): Promise<Tshirt[]>;

  /** Inserts a new shirt row and returns it. */
  create(data: { registrationId: number; gender: Gender | null; size: TshirtSize; isIncluded: boolean }): Promise<Tshirt>;

  /** Updates size and/or gender on an existing shirt row. Cosmetic — never changes row count. */
  update(id: number, data: { gender?: Gender | null; size?: TshirtSize }): Promise<void>;

  /** Deletes a shirt row. */
  delete(id: number): Promise<void>;

  /** Returns the count of extra (is_included = 0) shirt rows for a registration. */
  countExtras(registrationId: number): Promise<number>;
}

// ---------------------------------------------------------------------------
// Additional Charge
