export interface IAdditionalChargeRepository {
  /** Returns all charges for a registration, ordered created_at ASC. */
  findByRegistration(registrationId: number): Promise<AdditionalCharge[]>;

  /** Inserts a new charge row and returns it. Caller must validate amount > 0. */
  create(data: { registrationId: number; description: string; amount: number; createdBy: number }): Promise<AdditionalCharge>;

  /** Deletes a charge row. */
  delete(id: number): Promise<void>;
}

// ---------------------------------------------------------------------------
// Refund
// ---------------------------------------------------------------------------

export interface IRefundRepository {
  /** Inserts a new refund record and returns its autoincrement id.
   *  Overpayment inserts snapshot identity/source-payment facts from the live
   *  registration and payment (INSERT ... SELECT in the D1 implementation). */
  create(refund: NewRefund): Promise<{ id: number }>;

  /** Returns a single refund by id, or null if not found. Works for refunds
   *  whose live registration/payment has been deleted (detached owner). */
  findById(id: number): Promise<Refund | null>;

  /** Returns refunds, optionally filtered by status. Ordered by created_at DESC. */
  list(filters?: { status?: string }): Promise<Refund[]>;

  /** Returns refunds with live-or-snapshot owner mapping. All display fields
   *  (fullName, regCode, email, ownerKind) come from the refund row itself —
   *  no JOIN. Works for detached refunds after cancellation. */
  listWithRegistration(filters?: { status?: string }): Promise<Refund[]>;

  /** Returns all refunds for a specific registration. Ordered by created_at DESC. */
  findByRegistration(registrationId: number): Promise<Refund[]>;

  /** Returns all refunds whose immutable original_registration_id matches —
   *  works after the live registration row is deleted. Ordered by created_at DESC. */
  findByOriginalRegistration(originalRegistrationId: number): Promise<Refund[]>;
}

