// ---------------------------------------------------------------------------
// Bank Transaction
// ---------------------------------------------------------------------------

export interface IBankTransactionRepository {
  /**
   * Bulk-inserts transactions for one statement import. Dedup is enforced by
   * the txn_hash UNIQUE constraint (INSERT OR IGNORE) — re-importing an
   * overlapping statement range silently skips already-imported rows.
   */
  importBatch(
    transactions: NewBankTransaction[],
    importBatchId: string,
  ): Promise<{ inserted: number; skipped: number }>;

  /**
   * Returns a page of bank transactions matching the optional filters, each
   * with its linked payments, plus the total count matching the filters
   * (ignoring pagination). Defaults to page=1, limit=50.
   */
  list(
    filters?: BankTransactionFilters,
  ): Promise<{ transactions: BankTransactionWithLinks[]; total: number }>;

  /** Returns a single bank transaction with its linked payments, or null if not found. */
  getById(id: number): Promise<BankTransactionWithLinks | null>;

  /** Updates the staff comment on a transaction. Pass null to clear it. */
  updateComment(id: number, comment: string | null): Promise<void>;

  /** Links a payment to a bank transaction. Idempotent — re-linking an already-linked pair is a no-op. */
  linkPayment(bankTransactionId: number, paymentId: number): Promise<void>;

  /** Removes the link between a payment and a bank transaction. */
  unlinkPayment(bankTransactionId: number, paymentId: number): Promise<void>;

  /** Aggregate totals: sum of credits, sum of debits, latest balance. Respects date filters. */
  summary(filters?: { fromDate?: string; toDate?: string }): Promise<{
    totalCreditPaise: number;
    totalDebitPaise: number;
    latestBalancePaise: number;
    transactionCount: number;
  }>;
}

