// ---------------------------------------------------------------------------
// Feature Flags (feature-flags.spec.md, runtime-feature-flags.ispec.md)
// ---------------------------------------------------------------------------

export interface IFeatureFlagRepository {
  /** Returns every persisted override row. Rows for keys outside the catalog
   *  may be present (R1.3) — the caller ignores them. */
  findAll(): Promise<FeatureFlagOverride[]>;

  /** Returns the most recent `limit` feature-flag update audit entries,
   *  newest first, parsed from system_audit_log (action='feature_flags_updated'). */
  findRecentAudit(limit: number): Promise<FeatureFlagAuditEntry[]>;

  /**
   * Atomically upserts every given flag override and appends one
   * system_audit_log record in a single db.batch() call.
   * `auditDetails` is the caller-serialized JSON payload for the audit row
   * (this repository does not compute from/to values — the caller does).
   */
  applyChanges(
    changes: Array<{ key: string; enabled: boolean }>,
    actor: string,
    auditDetails: string,
  ): Promise<void>;
}

// ---------------------------------------------------------------------------
// Registration Desk (registration-desk-api.ispec.md)
// ---------------------------------------------------------------------------

export interface IDeskRepository {
  /**
   * Returns eligible (full_celebration / campus_only) registrations whose
   * full name or registration code matches the query term, as narrow desk
   * rows. Donation-only rows are excluded. The result is NOT capped — the
   * service ranks and slices with rankDeskSearch (desk-types.ts).
   */
  searchCandidates(query: string): Promise<DeskSearchRow[]>;

  /**
   * Returns eligible (full_celebration / campus_only) registrations that HAVE
   * a photo (`photo_thumb_key IS NOT NULL`) as narrow {id, photo_thumb_key}
   * rows, ordered by id. NOT filtered by check-in: the LED-wall photo
   * pre-cache manifest needs the whole expected roster before anyone arrives.
   * Rows without a photo are excluded — there is nothing to pre-cache.
   */
  listWallImageRows(): Promise<DeskWallImageRow[]>;

  /**
   * Returns one grouped counts row per eligible participation type
   * (`full_celebration` / `campus_only`), each with its total registration
   * count and how many are checked in. Donation-only is excluded. A type with
   * zero registrations is omitted — the caller defaults it to zero.
   */
  countStats(): Promise<DeskStatsRow[]>;

  /** Returns the narrow overview row for a registration code, or null. */
  findOverviewByCode(regCode: string): Promise<DeskOverviewRow | null>;

  /**
   * Returns the narrow overview row for a registration, or null when the id
   * does not exist. Donation-only registrations are still returned — the
   * service applies the eligibility rule (404 for donation-only).
   */
  findOverviewRow(id: number): Promise<DeskOverviewRow | null>;

  /**
   * Atomically records a check-in: `UPDATE ... SET checked_in_at = ?,
   * checked_in_by = ? WHERE id = ? AND checked_in_at IS NULL`. Returns
   * `{ wrote: true }` when the UPDATE changed a row (this call performed the
   * check-in) and `{ wrote: false }` when the registration was already
   * present (idempotent repeat or concurrent check-in — no second mutation).
   */
  markPresent(
    id: number,
    checkedInAt: number,
    checkedInBy: number,
    actorEmail: string,
  ): Promise<{ wrote: boolean }>;

  /**
   * Atomically clears a check-in: `UPDATE ... SET checked_in_at = NULL,
   * checked_in_by = NULL WHERE id = ? AND checked_in_at IS NOT NULL`.
   * Idempotent in both directions: returns `{ wrote: true }` when this call
   * cleared the check-in and `{ wrote: false }` when the registration was
   * already not present (repeat undo or never checked in). Pairs with
   * `markPresent` — the audit row distinguishes the two with separate
   * action codes.
   */
  markAbsent(
    id: number,
    actorEmail: string,
  ): Promise<{ wrote: boolean }>;

  /** Returns the stored idempotency row for (actorId, key), or null. */
  findIdempotency(actorId: number, key: string): Promise<DeskIdempotencyRow | null>;

  /**
   * Deletes idempotency rows older than `olderThanMs` (30-day retention). */
  pruneIdempotency(olderThanMs: number): Promise<void>;

  /**
   * Persists a desk spot registration atomically in ONE db.batch: the
   * registration row, all attendee rows, the payment_pending row, and the
   * actor-scoped idempotency row. A duplicate (actor_id, idem_key) UNIQUE
   * violation rolls back the entire batch — a concurrent retry can never
   * leave a registration without its idempotency record.
   *
   * Returns { id } of the new registration. The caller generates regCode and
   * pricing (both are server-owned); the batch binds them as given.
   */
  createSpotRegistration(
    data: RegistrationInsertSet,
    idempotency: {
      actorId: number;
      key: string;
      fingerprint: string;
      regCode: string;
      participationType: 'full_celebration' | 'campus_only';
      amountDue: number;
      actorEmail: string;
    },
  ): Promise<{ id: number }>;

  /**
   * Returns all t-shirt rows (the included shirt and any additional shirts)
   * for a registration, ordered included-first then by row id. Display only
   * — size, gender, and the included flag; never joins additional_charges.
   */
  findTshirts(registrationId: number): Promise<DeskTshirtRow[]>;
}

// ---------------------------------------------------------------------------
// Physical Room Assignment (room-assignment.spec.md)
// ---------------------------------------------------------------------------

export interface IRoomRepository {
  /** Throws on a duplicate room_number — the UNIQUE constraint is the source of truth. */
  createRoom(data: { roomNumber: string; notes: string | null }): Promise<Room>;

  /** All rooms (active and inactive), ordered by room_number ascending. */
  listRooms(): Promise<Room[]>;

  getRoomById(id: number): Promise<Room | null>;

  /**
   * Partial update. Only the provided keys are written. Returns null if no
   * room matches `id`. Throws on a duplicate room_number.
   */
  updateRoom(
    id: number,
    updates: { roomNumber?: string; notes?: string | null; isActive?: boolean },
  ): Promise<Room | null>;

  /**
   * Upserts on the (registration_id, night_date) unique key — a second call
   * for the same registration+night REPLACES the room_id/assigned_by rather
   * than creating a second row (room-assignment.spec.md R2).
   */
  upsertAssignment(data: {
    registrationId: number;
    roomId: number;
    nightDate: string;
    assignedBy: number;
  }): Promise<RoomAssignment>;

  /** True if a registrations row exists for `id`. */
  registrationExists(id: number): Promise<boolean>;

  /** A registration's assignments across all nights, joined with room display fields. */
  listAssignmentsByRegistration(registrationId: number): Promise<RegistrationRoomAssignment[]>;

  /**
   * A room's occupants, joined with registration display fields. When
   * `nightDate` is omitted, returns assignments for the room across all
   * nights.
   */
  listAssignmentsByRoom(roomId: number, nightDate?: string): Promise<RoomOccupant[]>;
}

// ---------------------------------------------------------------------------
// Memory Stories (memory-stories.spec.md, interfaces/memory-stories.ispec.md)
// ---------------------------------------------------------------------------

export type MemoryStoryVisibilityTransition =
  | { visibility: 'hidden'; comment: string; adminUserId: number; adminEmail: string; now: number }
  | { visibility: 'visible'; adminEmail: string; now: number };

export interface IMemoryStoryRepository {
  /** Visible stories only, newest published_at first, with a computed
   *  has_photo (0|1) flag joined from registrations.photo_thumb_key. */
  listVisible(): Promise<MemoryStoryVisibleRow[]>;

  /** Every story (visible and hidden), newest published_at first. */
  listAllForAdmin(): Promise<MemoryStoryRow[]>;

  /** Returns all stories owned by the given registration, newest
   *  published_at first. Up to STORIES_PER_PERSON_MAX rows (@smriti/shared). */
  findByRegistrationId(registrationId: number): Promise<MemoryStoryRow[]>;

  /** Returns the count of stories owned by the given registration. Used by
   *  the service layer to enforce STORIES_PER_PERSON_MAX before create(). */
  countByRegistrationId(registrationId: number): Promise<number>;

  /**
   * Inserts a new story with visibility='visible', published_at=now,
   * updated_at=now. The per-registration story-count limit is enforced by
   * the caller (service layer), not here.
   */
  create(input: {
    registrationId: number;
    authorName: string;
    authorBranch: string;
    text: string;
    now: number;
  }): Promise<MemoryStoryRow>;

  /**
   * Updates only text and updated_at on the row matching BOTH storyId and
   * registrationId. Preserves visibility, author snapshot, and published_at.
   * Returns null if no such row exists (wrong id, or not owned by
   * registrationId).
   */
  updateOwned(storyId: number, registrationId: number, text: string, now: number): Promise<MemoryStoryRow | null>;

  /**
   * Atomically deletes the row matching BOTH storyId and registrationId and
   * appends a 'memory_story_deleted' audit entry in one db.batch() call.
   * Returns false (no-op, no audit written) if no such row exists.
   */
  deleteOwned(storyId: number, registrationId: number, actor: string): Promise<boolean>;

  /**
   * Guarded visibility transition: only changes the row when its CURRENT
   * visibility differs from `transition.visibility` (repeat calls are
   * idempotent no-ops). `changed` reflects whether this call performed the
   * transition; `row` is the post-call row, or null if `id` does not exist.
   * An audit entry ('memory_story_hidden' / 'memory_story_unhidden') is
   * written only when `changed` is true.
   */
  setVisibility(
    id: number,
    transition: MemoryStoryVisibilityTransition,
  ): Promise<{ changed: boolean; row: MemoryStoryRow | null }>;
}
